import React, { useState, useEffect } from 'react';

function OrdersList() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const token = localStorage.getItem('token');

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        const res = await fetch('http://localhost/api/comandes', {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error('Error al obtenir les comandes');

        const data = await res.json();
        setOrders(data.dades || []);
      } catch (err) {
        console.error('Error fetching orders:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    fetchOrders();
  }, [token]);

  if (loading) return <p>Carregant comandes...</p>;
  if (error) return <p>Error: {error}</p>;
  if (orders.length === 0) return <p>No hi ha comandes disponibles.</p>;

  return (
    <div className="row">
      {orders.map(order => (
        <div key={order.id} className="col-md-6 mb-3">
          <div className="card h-100">
            <div className="card-body">
              <h5 className="card-title">Client: {order.client?.nom || 'Desconegut'}</h5>
              <p className="card-text"><strong>Proveïdor:</strong> {order.proveidor?.nom || 'Desconegut'}</p>
              <p className="card-text"><strong>Tipus:</strong> {order.tipus}</p>
              <p className="card-text"><strong>Data:</strong> {new Date(order.data).toLocaleDateString('ca-ES')}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

export default OrdersList;
